insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('hydraulics', 'advanced', 'module', 'm01-moving-the-string', 1, 'What produces surge pressure?', '["The pump starting.", "The string displacing mud, which has to flow up the annulus and costs pressure to move.", "The weight of the string, which compresses the mud column below it as it is lowered into the hole.", "The gel breaking as the string disturbs mud that has been standing since the last circulation."]'::jsonb, 1, 'It is annular pressure loss with a different velocity in it, and there is no separate surge physics in the engine.'),
  ('hydraulics', 'advanced', 'module', 'm01-moving-the-string', 2, 'Why are surge and swab symmetric about the mud weight?', '["Because it is the same annular flow with the sign of the direction reversed.", "Because the model assumes symmetry.", "Because the mud is incompressible, so the volume displaced going in equals the volume drawn going out.", "Because the clinging term is the same in both directions and it dominates the displaced volume term."]'::jsonb, 0, 'The magnitude is identical and only the direction of travel differs, and the engine reports both from one calculation.'),
  ('hydraulics', 'advanced', 'module', 'm01-moving-the-string', 3, 'Which of surge and swab lowers the pressure on the formation?', '["Surge, while running in.", "Both, since moving the string in either direction disturbs the mud column and reduces the effective head.", "Swab, while pulling out.", "Neither: both raise it, because moving the string always requires pushing mud through a restriction."]'::jsonb, 2, 'That is why most kicks on land wells happen while tripping out, and why the swab side is the one most easily forgotten.'),
  ('hydraulics', 'advanced', 'module', 'm01-moving-the-string', 4, 'Why is a surge-induced loss dangerous beyond the mud it costs?', '["It is only a cost issue.", "The fracture it creates propagates upward and can reach a shallower formation with a lower fracture gradient.", "The lost mud carries cuttings into the fracture, which plugs it and raises the pressure needed to circulate.", "Losing mud lowers the annulus level, which lowers the pressure and can then let a kick in."]'::jsonb, 3, 'That is how a single mistake becomes a well control event with two problems happening at once.'),
  ('hydraulics', 'advanced', 'module', 'm01-moving-the-string', 5, 'What does a CLOSED string displace?', '["Only its steel.", "Its whole outside cross-sectional area.", "Its inside area, since the mud inside is what has to be pushed out of the way as the string descends.", "Nothing: a closed string is sealed, so the mud inside it moves down with it and displaces nothing."]'::jsonb, 1, 'A float valve, a plugged bit or a casing float shoe all make a string closed, and casing is almost always closed.'),
  ('hydraulics', 'advanced', 'module', 'm01-moving-the-string', 6, 'What does an OPEN string displace?', '["Its whole outside area.", "Its steel plus the clinging layer, which is why the clinging constant is applied only to the open case.", "Only its steel, because mud can flow up the inside.", "Half its outside area, since the flow splits evenly between the inside and the annulus."]'::jsonb, 2, 'For this drill pipe the steel is 0.2686329600000001 of the outside area, so an open string displaces about a quarter of a closed one.'),
  ('hydraulics', 'advanced', 'module', 'm01-moving-the-string', 7, 'Why is the closed-to-open pressure ratio only about 1.17 rather than about 4?', '["Because the clinging term is present in both and does not scale with the displaced volume.", "Because the model caps the ratio.", "Because the mud flowing up the inside of an open string has its own pressure loss, which is nearly as large.", "Because the annular flow is turbulent in the closed case and laminar in the open one, which flattens the difference."]'::jsonb, 0, 'The internal loss is a real second reason and it is the smaller one. The clinging term is why the two cases are so close.'),
  ('hydraulics', 'advanced', 'module', 'm01-moving-the-string', 8, 'What is the clinging constant, and what does it multiply?', '["0.95, and it multiplies the area.", "0.45, and it multiplies the displaced volume rate, which is why an open string''s correction is smaller.", "It is fitted per well from an observed surge pressure, in the same way a friction factor is fitted.", "0.45, and it multiplies the trip speed to give an extra effective velocity."]'::jsonb, 3, 'It is Burkhardt''s empirical constant, published values range from about 0.4 to 0.5, and it is one of the method''s four conventions.'),
  ('hydraulics', 'advanced', 'module', 'm01-moving-the-string', 9, 'Why does the closed-to-open ratio grow with trip speed?', '["Because the clinging term grows faster.", "Because the closed string''s displaced volume grows as the square of the speed and the open one''s grows linearly.", "Because the pressure loss is nonlinear in velocity and the two cases sit at different points on the curve.", "Because the open string''s internal flow becomes turbulent at higher speed, which raises its pressure disproportionately."]'::jsonb, 2, 'Both terms are proportional to speed, so the velocity ratio is constant. The pressure ratio is not, and it goes from about 1.12 to about 1.24.'),
  ('hydraulics', 'advanced', 'module', 'm01-moving-the-string', 10, 'What is the exponent relating surge pressure to trip speed on this well?', '["About 0.6, so doubling the speed does not double the pressure.", "Exactly 2.", "About 1.0, since the displaced volume is proportional to the speed and the pressure follows the volume.", "About 1.8, matching the turbulent friction factor''s dependence on the Reynolds number."]'::jsonb, 0, 'The annular flow is largely laminar and the mud is shear thinning, so the loss goes as velocity to a power near n.'),
  ('hydraulics', 'advanced', 'module', 'm01-moving-the-string', 11, 'What does the exponent below one mean for a driller?', '["Slowing down does not help.", "Slowing down helps, and it helps less than proportionally.", "Slowing down helps more than proportionally, so a small reduction in speed buys a large reduction in pressure.", "The pressure is independent of speed below a threshold, above which it rises as the square."]'::jsonb, 1, 'Halving the speed from 1.0 to 0.5 m/s takes about 34 percent off, and halving again takes rather less than another 34.'),
  ('hydraulics', 'advanced', 'module', 'm01-moving-the-string', 12, 'Why does a real trip produce a higher surge than this calculation?', '["Because the model uses the wrong mud.", "Because a real string is eccentric, which raises the annular pressure loss above the concentric calculation.", "Because a real trip is done with the pumps off, so the mud has gelled and the yield stress is higher.", "Because the peak speed during a stand exceeds the average, and there is an acceleration term besides."]'::jsonb, 3, 'Eccentricity LOWERS the loss. The peak velocity is the input the calculation should be given, and the acceleration term is not in it at all.'),
  ('hydraulics', 'advanced', 'module', 'm01-moving-the-string', 13, 'What is the worst surge case on a well?', '["Pulling drill pipe fast.", "Running the bottom hole assembly, since the collars are the largest outside diameter in the string.", "Running casing: a large closed string in a tight annulus.", "Breaking circulation at bottom, which combines the gel break with the pressure needed to start the flow."]'::jsonb, 2, 'Casing is almost always run with a float, its diameter is large, and the crew''s speed is set by how fast they make up joints.'),
  ('hydraulics', 'advanced', 'module', 'm01-moving-the-string', 14, 'How is the surge on a casing run managed?', '["Fill the string as it goes in, use a differential fill float, or run slower.", "Increase the mud weight.", "Rotate the casing, which converts the axial displacement into a tangential motion and reduces the surge.", "Circulate while running, which keeps the annulus moving and prevents the displaced volume accumulating."]'::jsonb, 0, 'All three appear in a casing running procedure, and the calculation behind them is this one.'),
  ('hydraulics', 'advanced', 'module', 'm01-moving-the-string', 15, 'Why is the horizontal well''s surge uplift nearly double the slant well''s?', '["Because its annulus is tighter.", "Because the equivalent mud weight divides by true vertical depth and the lateral adds none.", "Because its string is longer, so more of it is displacing mud into the annulus at any given moment.", "Because its mud is heavier, which raises the density term in the annular pressure loss expression."]'::jsonb, 1, 'It is the same mechanism that makes the equivalent circulating density worse there, and both wells carry the same mud.'),
  ('hydraulics', 'advanced', 'module', 'm02-the-pressure-window', 1, 'What is pore pressure?', '["The pressure the rock can withstand.", "The pressure at which the formation begins to take fluid, which is what a leak-off test measures.", "The pressure of the fluid in the rock''s pores.", "The hydrostatic pressure of a column of formation water from surface to the depth in question."]'::jsonb, 2, 'If the wellbore pressure falls below it, formation fluid flows in. That is a kick and it is the start of every blowout.'),
  ('hydraulics', 'advanced', 'module', 'm02-the-pressure-window', 2, 'At what pressure does rock stop containing the mud and start taking it?', '["The pressure at which the rock breaks and takes fluid.", "The pressure of the pore fluid.", "The overburden pressure, which is the weight of all the rock above the point and is the absolute upper limit.", "The pressure at which the casing shoe fails, which is what the shoe integrity test establishes."]'::jsonb, 0, 'Beyond costing mud, exceeding it lowers the annulus level, which lowers the pressure, which can then let a kick in.'),
  ('hydraulics', 'advanced', 'module', 'm02-the-pressure-window', 3, 'Where do the pore and fracture pressures come from?', '["This course computes them.", "Geomechanics: offset wells, leak-off tests, log prediction and seismic velocities.", "The mud programme, which specifies them as the design basis for the mud weight in each hole section.", "The drilling contractor, who supplies them as part of the rig''s operating envelope for the well."]'::jsonb, 1, 'This course takes them as given and asks whether the hydraulics fit inside them.'),
  ('hydraulics', 'advanced', 'module', 'm02-the-pressure-window', 4, 'What is a narrow window?', '["Two hundred kg/m3 or more.", "A window in which the static mud weight cannot be chosen, because the two limits cross over the section.", "Any window narrower than the difference between the two muds this course runs, which is 240 kg/m3.", "Fifty kg/m3 or less between the pore and fracture equivalent mud weights."]'::jsonb, 3, 'Every decision in this course becomes a constraint at that width, which is where managed pressure drilling comes from.'),
  ('hydraulics', 'advanced', 'module', 'm02-the-pressure-window', 5, 'Which three situations narrow the window?', '["High rate of penetration.", "Deviation, high temperature and a thick mud, all of which raise the equivalent circulating density.", "Depth, depletion, and deep water.", "A large hole size, a long open hole and a fast trip, which are the three things this course computes."]'::jsonb, 2, 'A depleted reservoir has a lower pore pressure than the shales around it, and deep water has a low fracture gradient for its depth.'),
  ('hydraulics', 'advanced', 'module', 'm02-the-pressure-window', 6, 'Which four pressures have to fit in the window?', '["The static mud weight, the equivalent circulating density, the surge and the swab.", "Pore, fracture, mud and pump.", "The pump pressure, the bit pressure, the annulus loss and the hydrostatic head at total depth.", "The mud weight while drilling, while tripping, while circulating and while shut in."]'::jsonb, 0, 'Two of the four go up from the mud weight and one goes down, so the mud weight is not in the middle of the window.'),
  ('hydraulics', 'advanced', 'module', 'm02-the-pressure-window', 7, 'Which of the four is BELOW the mud weight?', '["The surge, while running in.", "The swab, while pulling out.", "The equivalent circulating density, since the annulus loss reduces the pressure the formation feels.", "None of them: every operation adds pressure to the static column."]'::jsonb, 1, 'It is the only one below, and it is the one most easily forgotten because the fracture side gets checked first.'),
  ('hydraulics', 'advanced', 'module', 'm02-the-pressure-window', 8, 'How does the engine solve for a trip speed limit?', '["A closed-form inversion.", "It sweeps the speeds in the golden set and returns the fastest one that satisfies both conditions.", "Newton iteration on the derivative of the surge pressure with respect to the trip speed.", "Bisection on the speed, applying both conditions and returning the smaller answer."]'::jsonb, 3, 'The response is monotone in both directions: faster always means more pressure, so bisection converges.'),
  ('hydraulics', 'advanced', 'module', 'm02-the-pressure-window', 9, 'What does the solver return if speed zero already fails?', '["The maximum in its bracket.", "Null, since no valid answer exists and returning a number would suggest that one does.", "Zero, which says the static mud weight is already outside the window.", "The speed at which the surge condition alone is satisfied, ignoring the swab condition entirely."]'::jsonb, 2, 'That is a mud weight problem rather than a trip speed problem, and returning zero rather than a small number says so.'),
  ('hydraulics', 'advanced', 'module', 'm02-the-pressure-window', 10, 'Which condition binds when the mud weight sits close to the pore pressure?', '["The swab, so the limit is set by pulling out.", "The surge, running in.", "Both equally, since surge and swab are symmetric about the mud weight and therefore always bind together.", "Neither: a mud weight near the pore pressure has plenty of room below the fracture gradient."]'::jsonb, 0, 'Symmetric about the mud weight is exactly why the closer limit binds: the same pressure crosses the nearer boundary first.'),
  ('hydraulics', 'advanced', 'module', 'm02-the-pressure-window', 11, 'Why is the speed limit quoted separately for casing and for drill pipe?', '["Because casing is heavier.", "Because a closed string produces more pressure, so it permits a slower trip.", "Because casing is run more slowly anyway, so the calculation is done at a different reference speed.", "Because casing has no tool joints, so the clinging constant does not apply to it in the same way."]'::jsonb, 1, 'The two numbers can differ by a fifth or more, and the closed case is the one that binds.'),
  ('hydraulics', 'advanced', 'module', 'm02-the-pressure-window', 12, 'What is the total spread of the four pressures on the slant well at ordinary settings?', '["About 10 kg/m3.", "About 240 kg/m3, which is the difference between the two muds this course runs.", "It cannot be stated, because the surge depends on the trip speed and the ECD on the flow rate.", "About 98 kg/m3, from swab to equivalent circulating density."]'::jsonb, 3, 'A window narrower than that cannot accommodate both circulating at 0.025 m3/s and tripping at 0.5 m/s.'),
  ('hydraulics', 'advanced', 'module', 'm02-the-pressure-window', 13, 'Which of the four is largest on this well at those settings?', '["The surge, always.", "The swab, since it is the only one below the mud weight and has less room to work with.", "The equivalent circulating density, though the ranking is not general.", "The static mud weight, which dominates all three of the others by more than an order of magnitude."]'::jsonb, 2, 'On a well with a low flow rate and a fast trip the surge is larger, and on a horizontal well the two are closer.'),
  ('hydraulics', 'advanced', 'module', 'm02-the-pressure-window', 14, 'What does managed pressure drilling add that no other lever does?', '["Pressure when the pumps are off.", "A wider window.", "A lower equivalent circulating density, achieved by reducing the annular friction at the same flow rate.", "A faster trip speed, by allowing the surge to be vented through the choke as the string goes down."]'::jsonb, 0, 'Every other lever produces pressure only while circulating, and the step at every connection is the dangerous moment.'),
  ('hydraulics', 'advanced', 'module', 'm02-the-pressure-window', 15, 'Why is the step between circulating and not circulating the dangerous moment?', '["Because the pumps can be damaged.", "Because it happens at every connection, dozens of times a day, on a narrow-window well.", "Because the mud gels while the pumps are off, which raises the pressure needed to restart circulation.", "Because the string is stationary, so the cuttings settle onto the assembly and increase the sticking risk."]'::jsonb, 1, 'Both of the wrong answers are real problems with a connection. The pressure step is the one the window cares about.'),
  ('hydraulics', 'advanced', 'module', 'm03-what-goes-wrong', 1, 'What are the three severities of lost circulation?', '["Minor, major and catastrophic.", "Fracture, seepage and vugular, which classify losses by the mechanism rather than by the volume lost.", "Seepage, partial, and total losses.", "Static, dynamic and induced, which classify them by whether the pumps were running when they started."]'::jsonb, 2, 'Total losses means no returns at all, and the annulus level is falling with the pressure at the bottom.'),
  ('hydraulics', 'advanced', 'module', 'm03-what-goes-wrong', 2, 'Why are total losses a well control event?', '["Because the falling annulus level lowers the pressure, which can fall below the pore pressure.", "Because the mud is expensive.", "Because the fracture propagates upward toward a shallower formation with a lower fracture gradient.", "Because the pumps cavitate once the pit level falls below the suction, which stops circulation entirely."]'::jsonb, 0, 'Then fluid enters while mud is leaving, which is an underground blowout with one formation feeding another.'),
  ('hydraulics', 'advanced', 'module', 'm03-what-goes-wrong', 3, 'What is the primary indicator of losses at surface?', '["The standpipe pressure rising.", "The torque and drag rising, since the mud entering the formation carries cuttings that pack around the string.", "The flow out exceeding the flow in, since the formation is returning what it took.", "The pit volume falling."]'::jsonb, 3, 'It is monitored continuously for exactly this reason, and the standpipe pressure falls slightly rather than rising.'),
  ('hydraulics', 'advanced', 'module', 'm03-what-goes-wrong', 4, 'What is the first action on losses, and why?', '["Increase the mud weight.", "Stop pumping, because it removes the circulating uplift immediately.", "Pump a lost circulation material pill, which bridges the fracture and is the only action that addresses the cause.", "Pull off bottom, which reduces the pressure at the shoe by shortening the annulus below the bit."]'::jsonb, 1, 'It is free and its effect is exactly what the hydraulics calculation predicts: the ECD falls to the static mud weight.'),
  ('hydraulics', 'advanced', 'module', 'm03-what-goes-wrong', 5, 'What are the two mechanisms that take a well underbalanced while tripping out?', '["Losses and a pack-off.", "Swab and the gel breaking, which reduces the effective density of the mud column as the string disturbs it.", "Swab, and not filling the hole.", "The falling temperature as the string comes out, and the mud''s thermal contraction as it cools."]'::jsonb, 2, 'They act in the same direction and neither is visible at surface until the well flows.'),
  ('hydraulics', 'advanced', 'module', 'm03-what-goes-wrong', 6, 'What is the defence against not filling the hole?', '["A trip tank, which fills the hole automatically and measures how much it took.", "The standpipe pressure gauge.", "The active pit level, which shows the same volume change and is monitored continuously during every operation.", "The flow show meter, which detects any return flow from the well while the pumps are off."]'::jsonb, 0, 'The active pit is useless for it: a few hundred litres is invisible in a tank of tens of cubic metres.'),
  ('hydraulics', 'advanced', 'module', 'm03-what-goes-wrong', 7, 'The hole takes LESS mud than calculated coming out. What does that mean?', '["The hole is losing mud.", "Something else is filling the space, and the only candidate is formation fluid.", "The string is displacing less than calculated, which means a component''s dimensions were entered wrongly.", "The trip tank is leaking, which is the commonest cause of a discrepancy on a trip sheet."]'::jsonb, 1, 'Taking MORE than calculated is losses. Both are detected by comparing a measured volume against a computed one.'),
  ('hydraulics', 'advanced', 'module', 'm03-what-goes-wrong', 8, 'What is a pack-off?', '["A plugged bit nozzle.", "A section of hole that has washed out, which reduces the annular velocity and allows cuttings to settle.", "A cement plug set to isolate a loss zone, which packs off the annulus deliberately.", "The annulus closing around the string with cuttings, cavings or collapsed hole."]'::jsonb, 3, 'It shrinks the flow area, and the pressure loss goes as roughly the velocity squared, so halving the area quadruples the loss.'),
  ('hydraulics', 'advanced', 'module', 'm03-what-goes-wrong', 9, 'What is the clearest surface signature of a pack-off?', '["The pit volume falling.", "The flow out exceeding the flow in, since the restricted annulus forces mud to surface faster than it is pumped.", "The standpipe pressure rising with no change to the flow rate.", "The hookload falling, since the material in the annulus supports part of the string''s weight."]'::jsonb, 2, 'The torque and drag rise at the same time, and the combination of a pressure rise and a torque rise is a pack-off until proved otherwise.'),
  ('hydraulics', 'advanced', 'module', 'm03-what-goes-wrong', 10, 'Why is a pack-off dangerous in three ways?', '["It can fracture the formation, stick the string, and hide itself when the pumps stop.", "It only costs rig time.", "It can plug the bit, stall the mud motor, and stop the measurement-while-drilling telemetry from reaching surface.", "It raises the pump pressure, the torque and the hookload, all three of which are monitored continuously."]'::jsonb, 0, 'Stopping the pumps relieves the pressure and the pack-off may partly clear, so the evidence disappears while the cause remains.'),
  ('hydraulics', 'advanced', 'module', 'm03-what-goes-wrong', 11, 'What is the instinctive response to a pack-off, and why is it wrong?', '["Stopping the pumps, which hides it.", "Pumping harder, which is what fractures the formation.", "Working the string, which drags the assembly through the packed material and can jam it permanently.", "Raising the mud weight, which increases the buoyancy on the cuttings and makes the bridge harder to clear."]'::jsonb, 1, 'Reduce the rate immediately to avoid fracturing, work the string, then circulate carefully at a rate that clears without breaking down.'),
  ('hydraulics', 'advanced', 'module', 'm03-what-goes-wrong', 12, 'Which observation separates losses from a kick?', '["The standpipe pressure.", "The torque and drag, since a kick brings light fluid into the annulus and reduces the string''s buoyed weight.", "The flow out against the flow in, since both events change it and only a kick changes its direction.", "The pit volume: one falls and the other rises."]'::jsonb, 3, 'Both reduce the standpipe pressure a little, and only one adds volume to the system.'),
  ('hydraulics', 'advanced', 'module', 'm03-what-goes-wrong', 13, 'Why does the standpipe pressure fall for a kick?', '["Because the pumps slow down.", "Because the formation fluid dilutes the mud, which lowers its viscosity and therefore the friction loss.", "The influx is lighter than mud, so the annulus column is lighter and needs less pressure to push up.", "Because the influx displaces mud out of the annulus, which shortens the flow path the pump has to supply."]'::jsonb, 2, 'It is a subtle effect, which is why a small gas kick shows in the pit volume long before it shows in the pressure.'),
  ('hydraulics', 'advanced', 'module', 'm03-what-goes-wrong', 14, 'What does the hydraulics model contribute to detecting these events?', '["The baseline: every observation is a departure from an expected value.", "It detects them automatically.", "The fracture gradient and the pore pressure, which are the limits each observation is compared against.", "The cuttings concentration, which predicts a pack-off before it happens and gives time to react."]'::jsonb, 0, 'The limits come from geomechanics and the concentration is a leading indicator rather than a prediction. A rig with no computed pressure has to detect a change against a remembered one.'),
  ('hydraulics', 'advanced', 'module', 'm03-what-goes-wrong', 15, 'Which of the engine''s three warnings is a setup error rather than a result?', '["The low transport ratio warning.", "The geometry coverage warning.", "The high cuttings concentration warning, since a concentration above a few percent means the inputs are unrealistic.", "None of them: all three describe the answer rather than the inputs."]'::jsonb, 1, 'The other two are statements about the result, and both need a threshold the user supplies.'),
  ('hydraulics', 'advanced', 'module', 'm04-managing-the-window', 1, 'What can the mud weight NOT do?', '["Move all four pressures.", "Change the spread between the four pressures.", "Keep the static pressure above the pore pressure, which needs a trip margin on top of it.", "Affect the surge and swab, which depend on the annular friction rather than on the density."]'::jsonb, 1, 'The density is in every one of the friction terms too, so it moves all four together. What it cannot do is bring them closer.'),
  ('hydraulics', 'advanced', 'module', 'm04-managing-the-window', 2, 'Which lever moves only the equivalent circulating density?', '["The mud weight.", "The trip speed, which moves the surge and swab and leaves the circulating case untouched.", "The flow rate.", "The annulus size, which moves the ECD, the surge and the swab together since all three are annular losses."]'::jsonb, 2, 'Lower rate, smaller spread, worse cleaning. That is the trade in one line.'),
  ('hydraulics', 'advanced', 'module', 'm04-managing-the-window', 3, 'Which lever moves three of the four?', '["The trip speed.", "The flow rate, which moves the ECD directly and the surge and swab through the mud''s shear history.", "The string''s bore, which changes the pipe loss and therefore the pump pressure at every operation.", "The rheology, because the ECD, the surge and the swab are all annular pressure losses."]'::jsonb, 3, 'A thinner mud reduces all three, and it also worsens the cleaning, which is the interaction that catches people.'),
  ('hydraulics', 'advanced', 'module', 'm04-managing-the-window', 4, 'What is the ranking of levers for a narrow window?', '["Trip speed first, then rheology, then flow rate, then string state.", "Mud weight first, always.", "Flow rate first, since it is the only lever that can be changed while drilling without stopping the operation.", "String state first, since a closed string is a fifth worse and swapping to an open one is free."]'::jsonb, 0, 'The string state is often not a choice: casing has a float. The trip speed is free and entirely under the driller''s control.'),
  ('hydraulics', 'advanced', 'module', 'm04-managing-the-window', 5, 'What is the interaction that catches people when thinning the mud?', '["There is no interaction.", "It lowers the surge and raises the swab, so the window''s two sides move in opposite directions.", "It lowers the ECD and worsens the cleaning, so the flow rate has to rise, which raises the ECD again.", "It lowers the pump pressure, which lets a higher flow rate be used, which improves the cleaning for free."]'::jsonb, 2, 'Whether the net effect is a lower ECD depends on the numbers, and the only way to find out is to run both.'),
  ('hydraulics', 'advanced', 'module', 'm04-managing-the-window', 6, 'Why can this engine not compute a break-circulation pressure?', '["Because the pumps are not modelled.", "Because the Herschel-Bulkley yield stress has no time in it and the gel does.", "Because the calculation is steady state, so it cannot represent a pressure that decays after the pumps start.", "Because the gel strength is not one of the four dial readings the rheology fit takes as input."]'::jsonb, 1, 'The steady-state point is also true and is a separate limitation. The yield stress is what a just-sheared mud has; the gel is what a resting one has.'),
  ('hydraulics', 'advanced', 'module', 'm04-managing-the-window', 7, 'What is a progressive gel, and why is it unwanted?', '["One that never sets at all.", "One that sets so hard the pumps cannot break it, which is why gel strengths are capped in a mud programme.", "One that varies with temperature, which makes the break-circulation pressure depend on the depth.", "One whose 10-minute value is much above its 10-second value, so a long connection costs more pressure."]'::jsonb, 3, 'A flat gel strong enough to suspend barite and no stronger is the design target, and achieving it is a mud chemistry problem.'),
  ('hydraulics', 'advanced', 'module', 'm04-managing-the-window', 8, 'What are the three ways to reduce a break-circulation pressure?', '["Break slowly, break in stages while running in, and rotate first.", "Raise the mud weight.", "Pump a thinner pill ahead of the mud, circulate at the maximum rate, and use a larger nozzle area.", "Reduce the flow rate, shorten the connection and raise the temperature of the mud in the pits."]'::jsonb, 0, 'All three break the gel progressively rather than along the whole annulus at once, and the mud design is the fourth lever.'),
  ('hydraulics', 'advanced', 'module', 'm04-managing-the-window', 9, 'What does managed pressure drilling add to the bottom hole pressure equation?', '["A larger hydrostatic head.", "A reduced annular friction term, achieved by returning through a line rather than an open bell nipple.", "A back pressure term, applied at surface through a choke.", "A seabed pump term, which lifts the returns and removes the mud column above the seabed."]'::jsonb, 2, 'The seabed pump is dual gradient, which is a different technique. Two of the three terms are what this course computes.'),
  ('hydraulics', 'advanced', 'module', 'm04-managing-the-window', 10, 'Why does managed pressure drilling need a real-time hydraulics model?', '["It does not need one.", "Because the control loop compares a computed annular friction against a measured downhole pressure.", "Because the choke has to be set from the pump pressure, which the model computes from the flow rate.", "Because the rotating control device has a pressure rating that the model has to keep the system below."]'::jsonb, 1, 'It is the most demanding use a drilling hydraulics model gets put to, and it is why the annulus friction''s accuracy matters commercially.'),
  ('hydraulics', 'advanced', 'module', 'm04-managing-the-window', 11, 'What does managed pressure drilling NOT fix?', '["The connection pressure step.", "The equivalent circulating density, which still rises with flow rate exactly as it does without back pressure.", "The surge and swab, which are unaffected by a surface choke because they occur with the pumps off.", "The window itself."]'::jsonb, 3, 'The ECD still rises and the surge still occurs; the point is that back pressure can be adjusted to offset them. The window is fixed by the rock.'),
  ('hydraulics', 'advanced', 'module', 'm04-managing-the-window', 12, 'What does a trip sheet measure?', '["Displacement: how much mud the hole took or gave against how much was calculated.", "The trip speed.", "The surge and swab pressures, recorded from a downhole gauge at each stand as the string is run.", "The time each stand takes, from which the average trip speed and therefore the surge is inferred."]'::jsonb, 0, 'It is the same two displacement expressions the surge calculation uses, applied to a length rather than a speed.'),
  ('hydraulics', 'advanced', 'module', 'm04-managing-the-window', 13, 'How do the surge calculation and the trip sheet divide the work?', '["They compute the same thing.", "The surge calculation detects a kick and the trip sheet sets the speed limit that prevents one.", "One is a plan and the other is a measurement, and neither replaces the other.", "The trip sheet computes the displacement and the surge calculation checks it against the fracture gradient."]'::jsonb, 2, 'The calculation gives the speed limit; the sheet gives the volume check. The calculation cannot detect a kick at all.'),
  ('hydraulics', 'advanced', 'module', 'm04-managing-the-window', 14, 'Why is the trip tank rather than the active pit used for the fill measurement?', '["Because the active pit is in use.", "Because a few hundred litres is invisible in a tank of tens of cubic metres.", "Because the trip tank is calibrated and the active pit is not, so only one of them gives a reliable volume.", "Because the trip tank is above the flowline, so it fills the hole by gravity without a pump running."]'::jsonb, 1, 'The discrepancy being looked for is a fraction of a cubic metre, and the measurement has to resolve it.'),
  ('hydraulics', 'advanced', 'module', 'm04-managing-the-window', 15, 'What is the useful thing to give a driller before a trip?', '["The fracture gradient.", "The surge pressure at every trip speed, so the driller can choose one and know its consequence.", "A running tally of the mud used so far, which is what the trip sheet accumulates as the trip proceeds.", "An expected displacement per stand, worked out in advance."]'::jsonb, 3, 'An expected value that somebody worked out is far more useful than a tally with nothing to compare it against.'),
  ('hydraulics', 'advanced', 'module', 'm05-the-edges-of-the-model', 1, 'What does a steady-state model miss?', '["Everything that happens while something is changing.", "Turbulent flow.", "Any variation along the flow path, since a steady state means uniform conditions from the pump to surface.", "The rheology''s dependence on shear rate, which is a transient property of the fluid rather than a steady one."]'::jsonb, 0, 'Starting and stopping the pumps, accelerating the string, and the connection cycle are all transients.'),
  ('hydraulics', 'advanced', 'module', 'm05-the-edges-of-the-model', 2, 'How large is the acceleration term on a 3000 m column?', '["Negligible, under a kilopascal.", "About 4.3 MPa, which is several times the steady surge and is why transient models are always used.", "About 432000 Pa at 0.1 m/s2, which is comparable to the steady surge pressure.", "It cannot be estimated without a compressibility, since the column does not accelerate as a rigid body."]'::jsonb, 2, 'Against a steady surge of about 0.98 MPa at 0.5 m/s, a term of that size is not a small correction.'),
  ('hydraulics', 'advanced', 'module', 'm05-the-edges-of-the-model', 3, 'Which way does the acceleration term go during a stand?', '["It always subtracts.", "It adds while accelerating in and subtracts while decelerating.", "It always adds, since accelerating the mud requires pressure regardless of the direction of the motion.", "It cancels over a stand, since the acceleration and deceleration are equal and opposite."]'::jsonb, 1, 'So the peak pressure during a stand is higher than the steady calculation at the peak velocity, and it is why a computed surge is optimistic.'),
  ('hydraulics', 'advanced', 'module', 'm05-the-edges-of-the-model', 4, 'What should a steady-state surge calculation be given?', '["The average velocity.", "The velocity at which the string is moving when it passes the shallowest open hole, which is the weakest point.", "The velocity that produces the same displaced volume over the stand as the real varying motion does.", "The peak velocity, not the average."]'::jsonb, 3, 'Giving it the average understates the surge, and that is the commonest error in using a surge calculation.'),
  ('hydraulics', 'advanced', 'module', 'm05-the-edges-of-the-model', 5, 'What does temperature do to a computed ECD, and which way?', '["Lower than reality.", "It has no effect, because the rheology is measured at 120 F which is representative of the annulus temperature.", "The real mud is thinner downhole, so the computed ECD is HIGHER than reality.", "It depends on the depth: thinner in the lower part of the annulus and thicker in the riser, and the two cancel."]'::jsonb, 2, 'The riser effect is real in deep water. On a land well the thermal effect is a systematic five to fifteen percent of the uplift.'),
  ('hydraulics', 'advanced', 'module', 'm05-the-edges-of-the-model', 6, 'What does compressibility do, and which way?', '["The mud is denser at depth, so the real hydrostatic pressure is slightly higher.", "The mud is lighter at depth.", "It has no effect, because mud is treated as incompressible and a few tenths of a percent is below the model''s precision.", "It raises the friction loss, since a denser fluid has more inertia and therefore a larger pressure drop."]'::jsonb, 0, 'It partly offsets the thermal effect, which makes the mud less dense, and on a deep hot well the two are of similar size.'),
  ('hydraulics', 'advanced', 'module', 'm05-the-edges-of-the-model', 7, 'Why is the accidental cancellation between temperature and compressibility not a reason to omit both?', '["Because they are both large.", "Because it does not hold at every depth or in every mud.", "Because compressibility raises the pressure by more than temperature lowers it in every mud that is used.", "Because both are already included in the rheology fit through the dial readings taken at surface."]'::jsonb, 1, 'An oil-based mud is far more compressible and far more thermally sensitive, and there the two do not cancel.'),
  ('hydraulics', 'advanced', 'module', 'm05-the-edges-of-the-model', 8, 'How does the gel strength differ from the yield stress?', '["They are the same thing.", "The gel is measured at 3 rpm and the yield stress is extrapolated to zero shear rate from the two high readings.", "The gel applies to the annulus and the yield stress to the pipe, since the shear rates differ by two orders.", "The gel grows with time at rest and the yield stress has no time in it."]'::jsonb, 3, 'Both are measured on the same instrument in the same units, and only one of them is in this model.'),
  ('hydraulics', 'advanced', 'module', 'm05-the-edges-of-the-model', 9, 'What does eccentricity do to the annular pressure loss?', '["Raises it by the same amount.", "Leaves it unchanged, because the total flow area is the same whether the pipe is centred or on the low side.", "Lowers it, by twenty to forty percent in a fully eccentric annulus.", "Raises it in laminar flow and lowers it in turbulent, so the effect depends on the regime in each section."]'::jsonb, 2, 'Flow takes the wide side, and a given rate through a wider effective channel costs less pressure.'),
  ('hydraulics', 'advanced', 'module', 'm05-the-edges-of-the-model', 10, 'A pipe lying on the low side. Where are the cuttings and where is the flow?', '["Makes it much worse, because the cuttings are on the side with the least flow.", "Improves it, by raising the velocity.", "Leaves it unchanged, since the transport ratio depends on the mean annular velocity rather than its distribution.", "Improves it in a vertical hole and worsens it at angle, since the pipe only lies down when the hole is inclined."]'::jsonb, 0, 'So a concentric non-rotating model overstates the ECD a little and overstates the hole cleaning a lot.'),
  ('hydraulics', 'advanced', 'module', 'm05-the-edges-of-the-model', 11, 'Which way does pipe rotation move the annular pressure loss?', '["It always lowers it.", "Either: it thins the mud and it can also destabilise the flow into turbulence.", "It always raises it, since the tangential velocity adds to the axial one and the loss goes as the total velocity.", "It has no effect, because the tangential motion is perpendicular to the axial flow and the two do not interact."]'::jsonb, 1, 'It raises the total shear rate, which lowers the friction factor, and it can also make a laminar annulus turbulent.'),
  ('hydraulics', 'advanced', 'module', 'm05-the-edges-of-the-model', 12, 'Turning the string at 150 rpm in a deviated hole. What does it buy?', '["Nothing measurable.", "Helps slightly, by raising the shear rate at the low side and reducing the mud''s apparent viscosity there.", "Hurts, because a rotating pipe drags cuttings around the annulus rather than up it.", "Helps a great deal: it stirs a bed mechanically."]'::jsonb, 3, 'It is the single most effective bed removal mechanism there is, and it is absent from every model in this course.'),
  ('hydraulics', 'advanced', 'module', 'm05-the-edges-of-the-model', 13, 'Which five things does this course teach and not certify?', '["Only the cuttings beds.", "The pore pressure, the fracture gradient, the mud programme, the casing design and the bit selection.", "Transients, temperature and compressibility, gel strength, eccentricity and rotation, and cuttings beds.", "The rheology models, the friction factor correlations, the slip velocity, the clinging constant and the blend."]'::jsonb, 2, 'The second list is other courses'' subjects and the third is what this course DOES certify.'),
  ('hydraulics', 'advanced', 'module', 'm05-the-edges-of-the-model', 14, 'What does the go-live migration do about the scope statement?', '["Refuses to run if any graded field key names one of the excluded topics.", "Records it in a documentation table.", "Removes the lessons that mention them, so that the course content matches what the capstone actually grades.", "Adds a warning to the course description, so that a learner knows what the certificate does not cover."]'::jsonb, 0, 'It turns a claim in prose into a check the database enforces, which is the same pattern the other courses use.'),
  ('hydraulics', 'advanced', 'module', 'm05-the-edges-of-the-model', 15, 'What IS certified by this course?', '["Everything in the lessons.", "The steady-state hydraulics of a stated method on a concentric non-rotating annulus.", "The equivalent circulating density to within the five to fifteen percent that field comparisons find.", "The hole cleaning on any well, since the transport calculation is a force balance that holds at any inclination."]'::jsonb, 1, 'Pressure loss per element, the pump pressure and its split, the ECD profile, the vertical-transport cuttings calculation, and surge and swab.'),
  ('hydraulics', 'advanced', 'module', 'm06-the-expert-reading', 1, 'At the end of the Expert modules, which judgement are you certified in?', '["Computing a pump pressure.", "Whether four pressures fit inside one window, and what moves each of them.", "Saying how well the annulus is carrying cuttings and what flow rate would improve it.", "Choosing a mud weight, from the pore and fracture pressures a geomechanics study supplies."]'::jsonb, 1, 'The mud weight is chosen from limits this course does not compute. The other two are the earlier tiers.'),
  ('hydraulics', 'advanced', 'module', 'm06-the-expert-reading', 2, 'If the Expert tier had one line, what would it be?', '["Everything here is annular friction with a different velocity in it, and four of them share one window.", "Surge and swab are symmetric.", "A closed string displaces its whole outside area and an open one only its steel, which is the whole difference.", "The equivalent circulating density divides by true vertical depth, which is why a lateral raises it so sharply."]'::jsonb, 0, 'The wrong answers are all true statements from this tier or the last. The claim is the structure holding them together.'),
  ('hydraulics', 'advanced', 'module', 'm06-the-expert-reading', 3, 'What is the clinging constant, and what is its status?', '["0.95, a discharge coefficient.", "0.45, derived from the boundary layer thickness on a moving wall in a Newtonian fluid at low Reynolds number.", "0.45, an empirical constant from Burkhardt, and one of the method''s four conventions.", "It is fitted per well from an observed surge pressure, in the same way a friction factor is fitted."]'::jsonb, 2, 'Published values range from about 0.4 to 0.5, and some methods compute it rather than assuming it.'),
  ('hydraulics', 'advanced', 'module', 'm06-the-expert-reading', 4, 'The displaced volumes differ by nearly four. Why do the pressures not?', '["The model caps it at 1.2.", "The open string''s internal flow has its own loss, which is nearly as large as the annular one it avoids.", "The two cases are computed with different friction factors, since one annulus is laminar and the other turbulent.", "The clinging term is in both cases and does not scale with the displaced volume."]'::jsonb, 3, 'The internal loss is the smaller second reason. The steel is 0.2686329600000001 of the outside area, so the volumes differ by nearly four.'),
  ('hydraulics', 'advanced', 'module', 'm06-the-expert-reading', 5, 'Doubling the trip speed does not double the pressure. What does it do, and why?', '["About 0.6, because the annulus is largely laminar and the mud is shear thinning.", "Exactly 2, an inertial law.", "About 1.0, since the displaced volume rate is proportional to the speed and the loss follows the volume.", "About 1.8, matching the turbulent friction factor''s dependence on the Reynolds number in the annulus."]'::jsonb, 0, 'It means slowing down helps and helps less than proportionally, so there is a point beyond which it buys very little.'),
  ('hydraulics', 'advanced', 'module', 'm06-the-expert-reading', 6, 'How much of the window do the four pressures use on the slant well at ordinary settings?', '["About 20 kg/m3.", "About 98 kg/m3, from swab to equivalent circulating density.", "About 240 kg/m3, which is the difference between the heavy and light muds this course runs.", "It depends entirely on the mud weight, since all four are expressed relative to it."]'::jsonb, 1, 'A narrower window than that cannot accommodate both circulating at 0.025 m3/s and tripping at 0.5 m/s.'),
  ('hydraulics', 'advanced', 'module', 'm06-the-expert-reading', 7, 'Which of the four pressures is easiest to forget?', '["The equivalent circulating density.", "The static mud weight, which is chosen once at the start of a section and then not revisited.", "The swab, being the only one below the mud weight.", "The surge, which occurs only while running in and is therefore relevant on half the trips."]'::jsonb, 2, 'Most kicks happen while tripping out. Forgetting the swab is how, and the fracture side gets checked first because it is the larger number.'),
  ('hydraulics', 'advanced', 'module', 'm06-the-expert-reading', 8, 'Which six numbers does this tier''s capstone grade?', '["Six circulating densities.", "The three rheology fits and the four pressures the circulating system is made of, on the new mud.", "Two circulating densities, an annular velocity, a transport ratio, a concentration and a solved flow rate.", "A surge pressure, two equivalent mud weights, a ratio, a second well''s surge and a speed limit."]'::jsonb, 3, 'The two wrong answers are the Associate and Professional capstones, on the same new mud and the same fixtures.'),
  ('hydraulics', 'advanced', 'module', 'm06-the-expert-reading', 9, 'Why does the capstone use a trip speed of 0.75 m/s?', '["Because the lessons use 0.2, 0.5 and 1.0, and no graded value should be one a lesson printed.", "Because it is the average trip speed.", "Because it is the speed at which the closed and open cases produce the same pressure on this well.", "Because it is the fastest speed the stated window allows, which is what field 6 solves for."]'::jsonb, 0, 'The same principle applies to the mud and to the flow rate, and it is why every graded number has to be produced rather than recalled.'),
  ('hydraulics', 'advanced', 'module', 'm06-the-expert-reading', 10, 'What free check is available on the capstone''s first two fields?', '["They should be equal.", "The equivalent mud weight is the mud weight plus the pressure over gravity times the true vertical depth.", "The surge and swab equivalent mud weights should sum to twice the pressure, which is the symmetry condition.", "The closed pressure should be four times the open one, matching the ratio of the displaced volumes."]'::jsonb, 1, 'It costs one division and it catches an error in either of them, or in the true vertical depth being used.'),
  ('hydraulics', 'advanced', 'module', 'm06-the-expert-reading', 11, 'In the capstone''s window, which limit binds?', '["The surge, being the larger pressure.", "Both equally, since surge and swab are symmetric and the window is centred on the mud weight.", "The swab, because the mud weight sits closer to the pore limit.", "Neither: the window is wide enough that the maximum search speed is returned unchanged."]'::jsonb, 2, 'With 1320 mud, a fracture limit of 1400 leaves 80 above and a pore limit of 1260 leaves 60 below, so the nearer boundary binds.'),
  ('hydraulics', 'advanced', 'module', 'm06-the-expert-reading', 12, 'Which habit does this tier ask about trip speed?', '["Use the average over a stand.", "Use the maximum the window allows, since anything slower wastes rig time for no additional safety.", "Use the speed at which the surge equals the equivalent circulating density, which balances the two operations.", "Use the peak, not the average."]'::jsonb, 3, 'A steady-state calculation given an average understates the peak, and the peak is what fractures the formation.'),
  ('hydraulics', 'advanced', 'module', 'm06-the-expert-reading', 13, 'Six numbers are all called pressure. What does that oblige you to do?', '["Name the pressure, because six different numbers are all called pressure.", "Report everything in bar.", "Report the ECD profile rather than the value at total depth, since the deepest formation is not always the weakest.", "Report the method specification, since four of its seven points are conventions rather than derivations."]'::jsonb, 0, 'All three are habits this course teaches. Naming the pressure is the one that makes a number identifiable at all.'),
  ('hydraulics', 'advanced', 'module', 'm06-the-expert-reading', 14, 'What did this course take as given?', '["The mud''s rheology.", "The pore pressure and the fracture pressure.", "The string and the hole geometry, both of which come from the well design and torque and drag courses.", "The rate of penetration, which sets the cuttings feed rate and is supplied by the drilling programme."]'::jsonb, 1, 'Every comparison in the Expert tier was against limits this course does not compute, and they are the geomechanics course.'),
  ('hydraulics', 'advanced', 'module', 'm06-the-expert-reading', 15, 'What does this course hand to the torque and drag course?', '["The mud''s density.", "The equivalent circulating density, which raises the buoyancy factor and therefore the string''s buoyed weight.", "The cuttings beds it cannot model, which are the largest thing that course''s friction factor absorbs.", "The annular velocity, which sets the drag on the outside of the pipe as it is tripped through the mud."]'::jsonb, 2, 'Two models, one missing mechanism, and the way to see it is to watch both of them drift at once.'),
  ('hydraulics', 'advanced', 'final', null, 1, 'A casing string is being run with a float shoe on a narrow-window well. What is your concern?', '["The casing may not reach bottom.", "It is the worst surge case there is: a large closed string in a tight annulus.", "The float will not hold, so the casing will fill from below and the buoyancy calculation will be wrong.", "The cement will be contaminated, because the surge pushes mud ahead of the shoe into the open hole."]'::jsonb, 1, 'Casing running speeds are computed rather than chosen for exactly this reason, and the shoe track is where losses most often happen.'),
  ('hydraulics', 'advanced', 'final', null, 2, 'A driller reports the trip is being run at an average of 0.4 m/s. What do you need?', '["The peak, because a stand is not run at a constant speed.", "The stand length.", "The mud weight, since the surge is proportional to density and the average speed is the only other input.", "The string state, since a closed string surges about four times as hard as an open one at any speed."]'::jsonb, 0, 'The closed-to-open ratio is about 1.17, not four. The peak can be double the average, and the surge follows the peak.'),
  ('hydraulics', 'advanced', 'final', null, 3, 'The swab equivalent mud weight at 0.5 m/s is 40 kg/m3 below the mud weight. The pore pressure is 30 below. What follows?', '["The well is safe with margin.", "The well is safe, since the swab acts only at the bit and the pore pressure applies at the shallowest permeable zone.", "The well goes underbalanced at that trip speed, and the limit is lower.", "Nothing can be said without the fracture gradient, since the two limits have to be considered together."]'::jsonb, 2, 'The swab side is the one that lets a kick in, and it is the one that gets checked second because the fracture side is the larger number.'),
  ('hydraulics', 'advanced', 'final', null, 4, 'A well shows losses every time circulation is established and is fine when static. What is it?', '["The mud weight is too high.", "The gel is breaking and fracturing the formation, which would show as a spike rather than a steady loss.", "The pumps are being started too quickly, which produces an acceleration pressure the model does not compute.", "The circulating uplift is most of the window."]'::jsonb, 3, 'Both of the wrong answers are real mechanisms with the same symptom. The steady difference between static and circulating is the first thing to compute.'),
  ('hydraulics', 'advanced', 'final', null, 5, 'Returns have stopped completely. What do you do in the first minute?', '["Stop pumping, which removes the circulating uplift immediately.", "Pump a lost circulation pill.", "Raise the mud weight to regain control of the formation that is now underbalanced below the loss zone.", "Pull off bottom, which shortens the annulus and reduces the friction contribution at the loss zone."]'::jsonb, 0, 'It is free and its effect is exactly what the calculation predicts. The pill comes second.'),
  ('hydraulics', 'advanced', 'final', null, 6, 'The hole takes less mud than calculated on the way out. What is happening?', '["Mud is being lost.", "Formation fluid is filling the space, which is a kick.", "The string''s displacement was overestimated, which happens when a closed string is assumed and it is actually open.", "The trip tank is over-reading, which is the commonest instrument fault on a trip sheet."]'::jsonb, 1, 'Taking MORE than calculated is losses. Both are detected by comparing a measured volume against a computed one.'),
  ('hydraulics', 'advanced', 'final', null, 7, 'The standpipe pressure rises sharply and the torque rises with it. What is it?', '["A plugged nozzle.", "A washout, which raises the pressure by exposing more of the string''s inside surface to the flow.", "A pack-off.", "A kick, which raises the pressure as the influx displaces mud from the annulus."]'::jsonb, 2, 'A plugged nozzle raises the pressure and not the torque. A washout LOWERS the pressure, and a kick lowers it slightly too.'),
  ('hydraulics', 'advanced', 'final', null, 8, 'The annulus has bridged. What does a driller want to do that would make it worse?', '["Stopping the pumps.", "Working the string, which is what actually clears it and should be done immediately.", "Reducing the flow rate, which allows the material in the annulus to settle further and worsens the bridge.", "Pumping harder."]'::jsonb, 3, 'Reducing the rate is the right first action. Pumping harder is what fractures the formation.'),
  ('hydraulics', 'advanced', 'final', null, 9, 'A pack-off clears when the pumps are stopped. Is the problem solved?', '["No: the evidence has disappeared and the cause has not.", "Yes, the annulus is clear.", "Yes, provided the standpipe pressure returns to its computed value when the pumps are restarted.", "No, but the risk is now lower, because the material has settled to the low side and is out of the flow path."]'::jsonb, 0, 'That is one of the three ways a pack-off is dangerous, and it is why the pressure has to be watched on restart.'),
  ('hydraulics', 'advanced', 'final', null, 10, 'What does the acceleration term do that the steady surge calculation cannot?', '["It subtracts pressure.", "It adds pressure while the string accelerates, on top of the steady value at that velocity.", "It cancels over a stand, since the acceleration and deceleration are equal and opposite in magnitude.", "It is negligible on any string under 5000 m, which is why the steady calculation is used in practice."]'::jsonb, 1, 'On a 3000 m column at 0.1 m/s2 it is about 432000 Pa, against a steady surge of about 0.98 MPa at 0.5 m/s.'),
  ('hydraulics', 'advanced', 'final', null, 11, 'Two effects bias the computed ECD in opposite directions on a deep hot well. Which?', '["Cuttings and eccentricity.", "Rotation and eccentricity, which raise and lower the annular pressure loss respectively at the same rate.", "Temperature thins the mud and lowers the real loss; compressibility raises the hydrostatic head.", "Gel strength and the yield stress, which are the two ways the same mud property enters the calculation."]'::jsonb, 2, 'They are of similar size on a water-based mud and they do not cancel on an oil-based one.'),
  ('hydraulics', 'advanced', 'final', null, 12, 'Why is an oil-based mud a worse case for the temperature and compressibility omissions?', '["Because it is far more compressible and far more thermally sensitive than a water-based one.", "Because it is thicker.", "Because it gels harder, so the break-circulation pressure is larger and the transient is more severe.", "Because its rheology is measured at a different temperature, so the surface fit is not comparable."]'::jsonb, 0, 'The accidental cancellation on a water-based mud does not hold there, and the errors add rather than offsetting.'),
  ('hydraulics', 'advanced', 'final', null, 13, 'What does a break-circulation pressure depend on that this model does not have?', '["The flow rate.", "The mud''s compressibility, which determines how far the pressure wave travels before the flow starts.", "The pump''s ramp rate, which sets how quickly the pressure is applied to the gelled column.", "The gel strength, which grows with time at rest."]'::jsonb, 3, 'The ramp rate matters too and it is a transient. The gel is the property the model has no term for at all.'),
  ('hydraulics', 'advanced', 'final', null, 14, 'Why does breaking circulation in stages while running in help?', '["Because it warms the mud up.", "Because the gelled column being broken is never the full length of the hole.", "Because it lets the gel re-form between stages, which reduces the peak stress at any one point.", "Because it circulates the cuttings out progressively, which reduces the annulus''s bulk density."]'::jsonb, 1, 'Letting the gel re-form would make it worse. Breaking it progressively rather than all at once is the mechanism.'),
  ('hydraulics', 'advanced', 'final', null, 15, 'What does eccentricity do to the two answers this course produces?', '["Raises both.", "Lowers both, since the wide side carries most of the flow and the pressure and the transport both follow it.", "Lowers the pressure and worsens the cleaning.", "Raises the pressure and improves the cleaning, since the narrow side has a much higher local velocity."]'::jsonb, 2, 'So a concentric non-rotating model overstates the ECD a little and overstates the hole cleaning a lot.'),
  ('hydraulics', 'advanced', 'final', null, 16, 'Which is the single most effective bed removal mechanism, and is it in the model?', '["Flow rate, and it is.", "A high-viscosity sweep, and it is partly, through the effect of viscosity on the slip velocity.", "Reciprocation, and it is, through the surge and swab calculation''s displaced volume term.", "Rotation, and it is not."]'::jsonb, 3, 'The surge calculation computes the pressure of moving the string, not what that motion does to a bed.'),
  ('hydraulics', 'advanced', 'final', null, 17, 'Which of the five omissions would you implement first, and why?', '["Cuttings in the annulus density, because it is worth 11.6 kg/m3 per percent and needs no new data.", "Transients, being the largest.", "Rotation, since it is the most effective cleaning mechanism and the rotary speed is already recorded.", "Temperature, since a geothermal gradient is available on every well and the effect is systematic."]'::jsonb, 0, 'All three of the alternatives are defensible. The cuttings one is available immediately from the engine''s own other output.'),
  ('hydraulics', 'advanced', 'final', null, 18, 'Managed pressure drilling is proposed. What problem does it actually solve?', '["The narrow window itself.", "The step in pressure at every connection, when the pumps stop.", "The equivalent circulating density, by returning through a line rather than an open bell nipple.", "The surge and swab, by venting the displaced volume through the choke as the string moves."]'::jsonb, 1, 'It lets you sit precisely inside a narrow window rather than making it wider, and the connection step is what it removes.'),
  ('hydraulics', 'advanced', 'final', null, 19, 'What does a managed pressure system need from a hydraulics model?', '["A fracture gradient.", "A pump pressure, from which the choke setting is computed by subtracting the measured standpipe reading.", "A real-time annular friction, compared against a measured downhole pressure.", "A cuttings concentration, so that the annulus''s bulk density can be included in the control equation."]'::jsonb, 2, 'It is the most demanding use a drilling hydraulics model gets, and it is why the annulus friction''s accuracy matters commercially.'),
  ('hydraulics', 'advanced', 'final', null, 20, 'What does dual-gradient drilling change in deep water?', '["The mud weight downhole.", "The fracture gradient, by removing the seawater column''s contribution to the overburden at the seabed.", "The annular friction, since a seabed pump moves the returns and the riser no longer carries a flowing column.", "The column above the seabed becomes seawater rather than mud."]'::jsonb, 3, 'The riser friction does change and that is secondary. Removing the heavy column above the seabed is the point.'),
  ('hydraulics', 'advanced', 'final', null, 21, 'Stand by stand on the way out, what two numbers are set against each other?', '["A measured fill volume against a computed displacement.", "The trip speed against a limit.", "The surge pressure against the fracture gradient, stand by stand, using a downhole gauge.", "The active pit level against the trip tank level, which detects a leak between the two systems."]'::jsonb, 0, 'It is the same two displacement expressions the surge calculation uses, applied to a length rather than a speed.'),
  ('hydraulics', 'advanced', 'final', null, 22, 'Why can the surge calculation not detect a kick?', '["Because it has no pore pressure.", "Because it is a plan: it says how fast you may go, not what happened.", "Because it computes a steady state and a kick is a transient event the model cannot represent.", "Because it applies at the bit and a kick can enter anywhere along the open hole."]'::jsonb, 1, 'It has no pore pressure either, and that is why it cannot say whether a given swab is dangerous without one being supplied.'),
  ('hydraulics', 'advanced', 'final', null, 23, 'Which pair of levers cannot change the SPREAD between the four pressures?', '["The flow rate and the trip speed.", "The rheology and the annulus size, both of which move three of the four pressures together.", "The mud weight alone.", "The string state and the nozzle area, since neither of them affects the annular friction at all."]'::jsonb, 2, 'The nozzle area affects none of the four, which makes it a fifth category. Mud weight moves all four together and cannot bring them closer.'),
  ('hydraulics', 'advanced', 'final', null, 24, 'Thinning the mud to lower the ECD. What is the catch?', '["There is no catch.", "The surge and swab rise, since a thinner mud transmits the displaced volume''s pressure more efficiently.", "The pump pressure rises, because a thinner mud is more likely to be turbulent inside the drill pipe.", "The cleaning worsens, so the flow rate has to rise, which raises the ECD again."]'::jsonb, 3, 'The surge and swab FALL with a thinner mud, since they are annular losses. Whether the net ECD is lower depends on the numbers.'),
  ('hydraulics', 'advanced', 'final', null, 25, 'What exponent relates surge pressure to trip speed, and what does it mean?', '["About 0.6, so slowing down helps and helps less than proportionally.", "Exactly 2, so it helps a great deal.", "About 1.0, so halving the speed halves the pressure and the trade is easy to reason about.", "About 1.8, matching turbulent flow, so slowing down is by far the most effective lever available."]'::jsonb, 0, 'There is a point beyond which slowing down buys very little and costs a great deal of rig time.'),
  ('hydraulics', 'advanced', 'final', null, 26, 'Why is the closed-to-open pressure ratio speed dependent?', '["Because the clinging term grows faster.", "Because the pressure loss is nonlinear in velocity and the two cases sit at different points on the curve.", "Because the displaced volume for a closed string grows as the square of the speed and for an open one linearly.", "Because the open string''s internal flow becomes turbulent above about 0.5 m/s and its loss rises sharply."]'::jsonb, 1, 'Both velocities are proportional to speed, so their ratio is constant. The pressures'' ratio goes from about 1.12 at 0.2 m/s to about 1.24 at 1.0.'),
  ('hydraulics', 'advanced', 'final', null, 27, 'A window is 60 kg/m3 wide and the circulating uplift is 58. What is the finding?', '["There is adequate margin.", "The mud weight should be lowered by 58 kg/m3, which places the ECD at the middle of the window.", "Circulating at all takes the well essentially to the fracture gradient.", "The flow rate should be halved, which by the 0.75 exponent would take the uplift to about 35 kg/m3."]'::jsonb, 2, 'Halving the rate does help by that much and it also halves the cleaning. Lowering the mud weight that far would go below the pore pressure.'),
  ('hydraulics', 'advanced', 'final', null, 28, 'Which of the four pressures does a surface choke NOT reach?', '["The swab only.", "The static mud weight, which is set by the mud''s density and cannot be changed at surface.", "The equivalent circulating density, since the choke is downstream of the annulus and the friction is upstream.", "None: back pressure adds to all four."]'::jsonb, 3, 'That is exactly why managed pressure drilling works: back pressure is an additive term at every point in the annulus.'),
  ('hydraulics', 'advanced', 'final', null, 29, 'What does the engine''s geometry coverage warning actually do to the answer?', '["Skips those annulus spans, so the loss and the ECD are both understated.", "Applies zero friction there.", "Extends the deepest section upward, which is conservative because the deepest annulus is the tightest.", "Refuses to compute the surge and swab, since the annulus is where both of them are calculated."]'::jsonb, 0, 'Zero friction would at least be defined. Skipping means the length contributes nothing at all, by an unknown amount.'),
  ('hydraulics', 'advanced', 'final', null, 30, 'Which two of the engine''s warnings need a threshold the user supplies?', '["The geometry coverage warning.", "The transport ratio and the cuttings concentration.", "The laminar and turbulent regime labels, both of which depend on a critical Reynolds number that varies with the mud.", "The surge and swab pressures, which need a fracture gradient and a pore pressure to be interpreted."]'::jsonb, 1, 'The surge and swab do need limits and the engine does not warn on them at all. The geometry warning is a setup error rather than a result.'),
  ('hydraulics', 'advanced', 'final', null, 31, 'Why does the engine not warn about losses, a kick or a pack-off?', '["Because they are rare.", "Because those are monitoring functions that belong to the rig''s instrumentation rather than to a calculation.", "Because it has no fracture gradient, no pore pressure and no mechanism for a bridge.", "Because it does warn about all three, through the transport ratio, the concentration and the coverage flag."]'::jsonb, 2, 'It computes pressures and the comparison against limits is the user''s, which is the right division.'),
  ('hydraulics', 'advanced', 'final', null, 32, 'Which single measurement converts the model from a prediction into an interpolation?', '["The standpipe pressure.", "The trip tank volume, which measures the displacement the surge calculation assumes.", "The cuttings volume at the shakers, which measures the feed the transport calculation assumes.", "A downhole equivalent circulating density from a pressure-while-drilling tool."]'::jsonb, 3, 'All three are real measurements. Only the downhole pressure measures the quantity the model is actually being used to predict.'),
  ('hydraulics', 'advanced', 'final', null, 33, 'What is the honest summary of this course''s certified output?', '["Steady-state hydraulics of a stated method on a concentric non-rotating annulus.", "A complete hydraulics model.", "The pressures a well will actually see, verified against an independent implementation to better than 1e-6.", "The flow rate that cleans the hole without fracturing the formation, on any well and any geometry."]'::jsonb, 0, 'The 1e-6 is verification against another code rather than against a well, and field comparisons land within tens of percent.'),
  ('hydraulics', 'advanced', 'final', null, 34, 'Five things are taught and not certified. What enforces that?', '["Nothing enforces it.", "The content lint, which checks that every lesson mentioning them carries a scope warning at the top.", "The go-live migration, which refuses to run if a graded field names one of them.", "The capstone grader, which rejects an answer whose key matches one of the excluded topics."]'::jsonb, 2, 'It turns a claim in prose into a check the database enforces, which is the pattern every course in the series uses.'),
  ('hydraulics', 'advanced', 'final', null, 35, 'What did this course hand to the well control course?', '["The pore and fracture pressures.", "The swab that lets a kick in, and the ECD that has to be re-established after a shut-in.", "The cuttings concentration, which determines how much rock is in the annulus when the well is shut in.", "The pump pressure, which is what the kill sheet uses as its slow circulating rate reference."]'::jsonb, 1, 'The slow circulating rate reference is real and is measured rather than computed. The pore and fracture pressures come from geomechanics.'),
  ('hydraulics', 'advanced', 'final', null, 36, 'What did it hand to casing design?', '["The burst rating.", "The equivalent circulating density during the cement job, which sets the maximum displacement rate.", "The annular velocity behind the casing, which determines whether the cement will displace the mud cleanly.", "The surge pressures a casing run produces."]'::jsonb, 3, 'Both of the wrong answers are real cementing questions and they belong to the cementing course rather than this one.'),
  ('hydraulics', 'advanced', 'final', null, 37, 'A surge calculation is quoted to four significant figures. What carries one?', '["The clinging constant, which is 0.45 and is empirical.", "The mud density.", "The true vertical depth, which comes from a survey with its own uncertainty of tens of metres.", "The trip speed, which is an average over a stand rather than a measured instantaneous value."]'::jsonb, 0, 'The trip speed is also soft and it is an input rather than a constant. Moving the clinging constant from 0.4 to 0.5 moves the answer by a few percent.'),
  ('hydraulics', 'advanced', 'final', null, 38, 'What would you tell a driller in one sentence from this tier?', '["Always run as slowly as possible.", "Watch the standpipe pressure, since every one of the three events this tier describes changes it first.", "Run at the speed the calculation allows and let the trip tank tell you whether it was enough.", "Keep the pumps running through connections, since the pressure step is the dangerous moment on any well."]'::jsonb, 2, 'Two of the three events lower the standpipe pressure only slightly, and continuous circulation needs equipment most rigs do not have.'),
  ('hydraulics', 'advanced', 'final', null, 39, 'Which four statements should accompany a computed equivalent circulating density?', '["Its flow rate and its depth.", "It excludes cuttings, assumes concentric geometry, assumes no rotation and uses surface-temperature rheology.", "Its method specification, its software version, its date and the engineer who ran it.", "The pore pressure, the fracture pressure, the mud weight and the trip speed it is being compared against."]'::jsonb, 1, 'They are the difference between a number and a number somebody who was not in the room can use.'),
  ('hydraulics', 'advanced', 'final', null, 40, 'What is the relationship between the pressure this course computes and the limits it compares against?', '["Both come from this course.", "The limits are computed here and the pressures come from the rig''s instrumentation as measurements.", "Both come from geomechanics, and this course only converts between pressure and equivalent mud weight.", "The pressures are computed here and every limit comes from somewhere else."]'::jsonb, 3, 'A hydraulics answer with no limit attached has not been used for anything, and that is the closing habit of the whole course.'),
  ('hydraulics', 'advanced', 'final', null, 41, 'Why is the surge and swab agreement with the oracle at machine precision while the pump pressure is not?', '["Because surge is simpler physics.", "Because the surge calculation uses the clinging constant, which both implementations hard-code identically.", "Because the surge calculation is short and the pump pressure is the longest chain in the course.", "Because the surge is computed on fewer elements, since only the annulus below the reference depth is included."]'::jsonb, 2, 'The element count is a real second reason. Short chains agree at machine precision and long ones accumulate rounding.'),
  ('hydraulics', 'advanced', 'final', null, 42, 'A window allows a closed-string trip at 0.9 m/s and an open-string trip at 1.1. Which do you plan for?', '["The closed one, because that is what a casing run or a float will give you.", "The open one, being faster.", "The average of the two, since a drill string with a ported float is between the two extremes.", "Neither: plan for the speed at which the surge equals the equivalent circulating density."]'::jsonb, 0, 'The two numbers are quoted separately for exactly this reason, and the closed case is the one that binds.');
